window.AXIA_STATIC.articles = [{"slug": "fast-website", "title": "چطور یک وب‌سایت سریع بسازیم", "summary": "سرعت یک ویژگی نیست که در پایان اضافه شود؛ نتیجهٔ سه تصمیم درست از روز اول است.", "body": "## چرا سرعت مهم است\n\nکاربری که سه ثانیه منتظر می‌ماند، معمولاً برنمی‌گردد. سرعت یک ویژگی نیست که\nدر پایان پروژه اضافه شود؛ نتیجهٔ تصمیم‌هایی است که از روز اول گرفته می‌شود.\n\n## سه تصمیم که بیشترین اثر را دارند\n\n- **تصاویر را درست اندازه بگیرید.** یک تصویر ۴ مگابایتی که در قابی ۴۰۰ پیکسلی\n  نمایش داده می‌شود، فقط پهنای باند هدر نمی‌دهد، تجربه را هم خراب می‌کند.\n- **فونت را سبک نگه دارید.** یک خانوادهٔ متغیر با وزن‌های محدود، بهتر از چهار\n  فایل جداگانه است.\n- **جاوااسکریپت را به تعویق بیندازید.** کاری که برای اولین نمایش لازم نیست،\n  نباید اولین نمایش را معطل کند.\n\n## اندازه‌گیری، نه حدس\n\nپیش از هر بهینه‌سازی، عدد بگیرید. اگر ندانید صفحه در حال حاضر چند ثانیه طول\nمی‌کشد، نمی‌توانید بگویید تغییری که داده‌اید بهتر بوده یا بدتر.\n\n```html\n<img src=\"cover.webp\" width=\"1200\" height=\"630\" loading=\"lazy\" alt=\"تصویر مقاله\">\n```\n\n> آنچه اندازه‌گیری نشود، بهتر نمی‌شود.\n\n## جمع‌بندی\n\nسرعت از همان ابتدا در ساختار پروژه تصمیم گرفته می‌شود. سه تصمیم بالا بدون هیچ\nابزار اضافه‌ای، بیشترین تفاوت را می‌سازند.\n", "tags": ["سرعت", "وب", "تجربه کاربری"], "language": "fa", "published_at": "2026-11-08 22:22:45", "reading_minutes": 1}, {"slug": "wordpress-vs-code", "title": "وردپرس یا کدنویسی از صفر؛ کدام برای پروژهٔ شما درست است؟", "summary": "وردپرس در چند روز یک سایت قابل استفاده می‌دهد و کدنویسی از صفر کنترل کامل. تفاوت واقعی در سرعت راه‌اندازی نیست؛ در هزینهٔ پنج‌ساله و جایی است که روزی به دیوار می‌خورید.", "body": "## یک سؤال اشتباه، و یک سؤال درست\n\nبحث همیشگی این است: «وردپرس یا کد؟» اما این سؤال جواب درستی ندارد، چون هر دو\nابزارند و ابزار بدون هدف معنا ندارد. سؤال درست این است: در دو سال آینده، چه\nچیزی بیشتر به کسب‌وکار شما آسیب می‌زند — دیر راه افتادن، یا گیر کردن در ساختاری\nکه نمی‌توانید تغییرش دهید؟\n\nپاسخ این دو سؤال معمولاً یکی نیست، و همین است که بحث را طولانی می‌کند.\n\n## وردپرس دقیقاً چه کاری می‌کند\n\nوردپرس یک سیستم مدیریت محتواست: پایگاه داده، پنل مدیریت، سیستم قالب و چند هزار\nافزونهٔ آماده. برای سایتی که محتوایش مرتب عوض می‌شود و شکلش ثابت است، این ترکیب\nبسیار کارآمد است. مدیر سایت بدون دانش فنی می‌تواند مقاله بنویسد، عکس عوض کند و\nمنو بسازد. تحویل پروژه هم ساده است، چون هر کسی که وردپرس می‌شناسد می‌تواند\nادامه‌اش را بگیرد.\n\nهزینهٔ پنهانش جایی ظاهر می‌شود که سایت از قالب عمومی خارج می‌شود: هر افزونه یک\nوابستگی است، هر وابستگی یک نقطهٔ شکست و یک به‌روزرسانی که ممکن است سایت را بشکند.\n\n## کدنویسی از صفر دقیقاً چه کاری می‌کند\n\nدر ساخت اختصاصی، شما فقط چیزی را می‌سازید که لازم دارید. صفحه‌ای که در وردپرس با\nیک قالب سنگین و چهار افزونه ساخته می‌شود، می‌تواند یک فایل HTML و کمی CSS باشد که\nدر کمتر از یک ثانیه باز می‌شود.\n\nبهایش این است که هر تغییر بعدی به یک نفر نیاز دارد. اگر تیم شما کسی را برای\nنوشتن مقاله ندارد، یک سایت اختصاصی بی‌پنل ممکن است تبدیل به سایت رهاشده شود؛\nاین هم یک شکست است، فقط آرام‌تر.\n\n## مقایسهٔ رو‌در‌رو\n\n| معیار | وردپرس | کدنویسی از صفر |\n| --- | --- | --- |\n| زمان تا اولین انتشار | چند روز تا چند هفته | چند هفته تا چند ماه |\n| هزینهٔ شروع | پایین | بالاتر |\n| سرعت بارگذاری | متوسط؛ به قالب و افزونه‌ها بستگی دارد | کاملاً در کنترل شما |\n| ویرایش محتوا بدون برنامه‌نویس | بله، با پنل مدیریت | فقط اگر پنل ساخته شود |\n| فرم یا منطق اختصاصی | نیاز به افزونه یا کد درون قالب | بخشی از طراحی اولیه |\n| امنیت | سطح حملهٔ گسترده؛ به‌روزرسانی مداوم لازم است | سطح حملهٔ کوچک‌تر و مشخص‌تر |\n| هزینهٔ نگهداری پنج‌ساله | افزونه‌ها، مجوزها، به‌روزرسانی‌ها | میزبانی و نگهداری کد |\n| وابستگی به افراد | کم؛ بازار بزرگ | زیاد؛ تیم یا پیمانکار مشخص |\n\nاین جدول هیچ برنده‌ای ندارد. هر ردیف یک هزینه است، و پروژهٔ شما بعضی از این\nهزینه‌ها را می‌تواند بپردازد و بعضی را نه.\n\n## جایی که تصمیم مشخص می‌شود\n\nسه پرسش را صادقانه جواب دهید:\n\n1. **محتوای سایت چند وقت یک‌بار عوض می‌شود؟** اگر هفته‌ای چند بار، پنل مدیریت\n   وردپرس صرفه‌جویی واقعی است.\n2. **آیا منطق سایت از قالب‌های آماده جلوتر می‌رود؟** اگر بله، هر روز که با وردپرس\n   می‌مانید، هزینهٔ عقب کشیدن بیشتر می‌شود.\n3. **چه کسی سال آینده این سایت را نگه می‌دارد؟** اگر جواب «هیچ‌کس» است، ساده‌ترین\n   ساختار ممکن بهترین انتخاب است، نه پیشرفته‌ترین.\n\n## گزینهٔ سوم که کمتر گفته می‌شود\n\nاین یک انتخاب دوتایی نیست. ساخت اختصاصی با یک پنل سبک برای بخش‌هایی که واقعاً\nتغییر می‌کنند، هم سرعت و کنترل کد را می‌دهد و هم مدیر سایت را از برنامه‌نویس\nبی‌نیاز می‌کند. هزینه‌اش بین دو سر طیف است، اما برای بیشتر پروژه‌های واقعی\nنقطهٔ تعادل همین‌جاست.\n\n## جمع‌بندی\n\nوردپرس برای سایتی درست است که محتوایش زیاد و شکلش ثابت است. کدنویسی از صفر برای\nسایتی درست است که شکل و رفتارش بخشی از ارزش آن است. اگر مطمئن نیستید کدام‌اید،\nبا کوچک‌ترین نسخهٔ قابل استفاده شروع کنید؛ تصمیم درست را می‌شود بعداً گرفت، اما\nساختاری که اشتباه انتخاب شده را فقط با هزینه می‌شود عوض کرد.", "tags": ["وردپرس", "توسعه وب", "انتخاب فناوری"], "language": "fa", "published_at": "2026-11-20 10:15:00", "reading_minutes": 1}];
